require_once 'config.php';require_role('student');$jobId=filter_input(INPUT_GET,'job_id',FILTER_VALIDATE_INT) ?: filter_input(INPUT_POST,'job_id',FILTER_VALIDATE_INT);$s=$pdo->prepare("SELECT * FROM jobs WHERE id=? AND status='published'");$s->execute([$jobId]);$job=$s->fetch();if(!$job){flash('error','That opportunity is no longer available.');redirect('jobs.php');}if(!job_is_open($job)){flash('error','Applications for this opportunity have closed.');redirect('job.php?id='.$jobId);}$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(trim($_POST['cover_note']??'')==='')$cover='';else $cover=trim($_POST['cover_note']);$file=$_FILES['resume']??null;if(!$file||$file['error']===UPLOAD_ERR_NO_FILE)$errors[]='Please attach your resume.';elseif($file['error']!==UPLOAD_ERR_OK)$errors[]='The upload failed. Please try again.';elseif($file['size']>MAX_RESUME_SIZE)$errors[]='Your resume must be 5 MB or smaller.';else{$finfo=new finfo(FILEINFO_MIME_TYPE);$mime=$finfo->file($file['tmp_name']);$allowed=['application/pdf'=>'pdf','application/msword'=>'doc','application/vnd.openxmlformats-officedocument.wordprocessingml.document'=>'docx'];if(!isset($allowed[$mime]))$errors[]='Upload a PDF, DOC, or DOCX resume.';}
if(!$errors){$s=$pdo->prepare('SELECT id FROM applications WHERE job_id=? AND user_id=?');$s->execute([$jobId,current_user()['id']]);if($s->fetch())$errors[]='You have already applied for this opportunity.';else{$folder=__DIR__.'/uploads/resumes';if(!is_dir($folder))mkdir($folder,0750,true);$filename=bin2hex(random_bytes(18)).'.'.$allowed[$mime];if(!move_uploaded_file($file['tmp_name'],$folder.'/'.$filename))$errors[]='We could not save your resume. Please try again.';else{$s=$pdo->prepare('INSERT INTO applications(job_id,user_id,resume,cover_note,status) VALUES(?,?,?,?,?)');$s->execute([$jobId,current_user()['id'],$filename,$cover,'Submitted']);flash('success','Application sent! You can track its progress in My applications.');redirect('my_applications.php');}}}}
$pageTitle='Apply · '.$job['title'];require 'includes/header.php'; ?>
<section class="form-page"><a class="back-link" href="job.php?id=<?= (int)$job['id'] ?>">← Back to role details</a><div class="form-page-head"><div class="eyebrow">ONE STEP CLOSER</div><h1>Make your <span class="text-accent">move.</span></h1><p>You're applying for <strong><?= e($job['title']) ?></strong> at <?= e($job['company_name']) ?>.</p></div><div class="form-card"><div class="form-card-heading"><span class="step-number">01</span><div><h2>Your application</h2><p>Share a little about yourself with the team.</p></div></div><?php if($errors): ?><div class="alert alert-error" role="alert"><?php foreach($errors as $er): ?><div><?= e($er) ?></div><?php endforeach; ?></div><?php endif; ?><form method="post" enctype="multipart/form-data" class="form-stack"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="job_id" value="<?= (int)$job['id'] ?>"><label class="form-field">Resume <span class="required">*</span><span class="upload-box"><input type="file" name="resume" accept=".pdf,.doc,.docx,application/pdf,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document" required><span class="upload-icon">↑</span><strong>Choose your resume</strong><small>PDF, DOC or DOCX · up to 5 MB</small></span></label><label class="form-field">A note to the team <span class="optional">Optional</span><textarea name="cover_note" rows="5" maxlength="2000" placeholder="What interests you about this opportunity? What would you love to bring to the team?"><?= e($_POST['cover_note']??'') ?></textarea><span class="field-hint">A few genuine sentences can help your application stand out.</span></label><div class="form-actions"><a class="button button-quiet" href="job.php?id=<?= (int)$job['id'] ?>">Cancel</a><button class="button button-primary" type="submit">Submit application <span>↗</span></button></div></form></div><p class="privacy-note">♧ Your resume will only be shared with the organization reviewing this application.</p></